use chrono::{DateTime, Utc, NaiveDate, NaiveDateTime, TimeZone};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContentFrontMatter {
    pub title: Option<String>,
    pub date: Option<String>,
    pub tags: Option<Vec<String>>,
    pub description: Option<String>,
    pub authors: Option<Vec<String>>,
    pub author: Option<String>,
    pub stream: Option<String>,
    pub series: Option<String>,
    pub pinned: Option<bool>,
    pub slug: Option<String>,
    pub banner_image: Option<String>,
    pub card_image: Option<String>,
    pub toc: Option<bool>,
    pub extra: Option<Value>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContentItem {
    pub title: String,
    pub slug: String,
    pub date: Option<DateTime<Utc>>,
    pub tags: Vec<String>,
    pub description: Option<String>,
    pub authors: Vec<String>,
    pub stream: Option<String>,
    pub series: Option<String>,
    pub pinned: bool,
    pub banner_image: Option<String>,
    pub card_image: Option<String>,
    pub toc: Option<String>,
    pub html: String,
    pub extra: Option<Value>,
    pub source_path: Option<String>,
    pub back_links: Vec<BackLink>,
    pub previous: Option<Box<ContentRef>>,
    pub next: Option<Box<ContentRef>>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContentRef {
    pub slug: String,
    pub title: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackLink {
    pub slug: String,
    pub title: String,
}

pub fn parse_date(date_str: &str) -> Option<DateTime<Utc>> {
    let date_str = date_str.trim();

    // Try various formats
    // ISO 8601 with timezone
    if let Ok(dt) = DateTime::parse_from_rfc3339(date_str) {
        return Some(dt.with_timezone(&Utc));
    }

    // YYYY-MM-DD
    if let Ok(d) = NaiveDate::parse_from_str(date_str, "%Y-%m-%d") {
        let dt = NaiveDateTime::new(d, chrono::NaiveTime::from_hms_opt(0, 0, 0).unwrap());
        return Some(Utc.from_utc_datetime(&dt));
    }

    // YYYY-MM-DDTHH:MM:SS
    if let Ok(dt) = NaiveDateTime::parse_from_str(date_str, "%Y-%m-%dT%H:%M:%S") {
        return Some(Utc.from_utc_datetime(&dt));
    }

    None
}
