use include_dir::{include_dir, Dir};
use std::path::{Path, PathBuf};
use std::fs;

pub static ASSETS: Dir<'_> = include_dir!("$CARGO_MANIFEST_DIR/assets");

pub struct EmbeddedFile {
    pub path: &'static str,
    pub content: &'static [u8],
}

pub fn get_static_files() -> Vec<(&'static str, &'static [u8])> {
    let mut files = vec![];
    collect_files(&ASSETS, "", &mut files);
    files
}

fn collect_files<'a>(dir: &'a Dir<'_>, prefix: &str, files: &mut Vec<(&'a str, &'a [u8])>) {
    for file in dir.files() {
        files.push((file.path().to_str().unwrap_or(""), file.contents()));
    }
    for subdir in dir.dirs() {
        collect_files(subdir, prefix, files);
    }
}

pub fn write_embedded_file(output_dir: &Path, rel_path: &str, content: &[u8]) -> anyhow::Result<()> {
    let dest = output_dir.join(rel_path);
    if let Some(parent) = dest.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(&dest, content)?;
    Ok(())
}

pub fn get_template(name: &str) -> Option<&'static str> {
    let path = format!("templates/{}", name);
    ASSETS.get_file(&path)
        .and_then(|f| f.contents_utf8())
}

pub fn get_static_content(name: &str) -> Option<&'static [u8]> {
    let path = format!("static/{}", name);
    ASSETS.get_file(&path).map(|f| f.contents())
}
RUST

