use regex::Regex;
use std::collections::HashMap;
use tera::{Tera, Context, Value};
use once_cell::sync::Lazy;

pub const DEFAULT_SHORTCODE_PATTERN: &str = r#"<!-- \.(\w+)(?:\s+([^-][\s\S]*?))?\s*-->"#;

static SHORTCODE_REGEX: Lazy<Regex> = Lazy::new(|| {
    Regex::new(DEFAULT_SHORTCODE_PATTERN).unwrap()
});

pub fn parse_args(args_str: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();
    // Parse key=value pairs
    let re = Regex::new(r#"(\w+)=(?:"([^"]*)"|([\S]+))"#).unwrap();
    for cap in re.captures_iter(args_str) {
        let key = cap[1].to_string();
        let val = cap.get(2)
            .or_else(|| cap.get(3))
            .map(|m| m.as_str().to_string())
            .unwrap_or_default();
        map.insert(key, val);
    }
    map
}

pub struct Shortcodes {
    pub tera: Tera,
    pub pattern: Regex,
}

impl Shortcodes {
    pub fn new(pattern: Option<&str>) -> Self {
        let pat = pattern.unwrap_or(DEFAULT_SHORTCODE_PATTERN);
        let regex = Regex::new(pat).unwrap_or_else(|_| SHORTCODE_REGEX.clone());
        Shortcodes {
            tera: Tera::default(),
            pattern: regex,
        }
    }
}
