# ============================================================
# TEMPLATE SETUP
# ============================================================

def setup_tera(input_folder, config, output_dir=None):
    """Set up the template engine with all templates"""
    engine = TeraTemplate()

    # Determine template directory
    theme = config.get('theme')
    theme_dir = None

    if theme:
        # Look for theme in input folder
        theme_dir = os.path.join(input_folder, theme)
        if not os.path.exists(theme_dir):
            log.warning(f"Theme directory not found: {theme_dir}")
            theme_dir = None

    templates_path = config.get('templates_path', 'templates')
    user_templates_dir = os.path.join(input_folder, templates_path)

    # Load templates in priority order:
    # 1. Embedded defaults
    # 2. Theme templates
    # 3. User templates

    # First load embedded templates
    for rel_path, content in EMBEDDED_FILES.items():
        if rel_path.startswith('templates/'):
            tname = rel_path[10:]  # Remove 'templates/' prefix
            engine.add_template(tname, content.decode('utf-8'))

    # Load theme templates (override embedded)
    if theme_dir:
        theme_templates = os.path.join(theme_dir, 'templates')
        if os.path.exists(theme_templates):
            for fname in os.listdir(theme_templates):
                if fname.endswith(('.html', '.xml')):
                    fpath = os.path.join(theme_templates, fname)
                    with open(fpath, 'r', encoding='utf-8') as f:
                        engine.add_template(fname, f.read())

    # Load user templates (override everything)
    if os.path.exists(user_templates_dir):
        for fname in os.listdir(user_templates_dir):
            if fname.endswith(('.html', '.xml')):
                fpath = os.path.join(user_templates_dir, fname)
                with open(fpath, 'r', encoding='utf-8') as f:
                    engine.add_template(fname, f.read())

    return engine, theme_dir


def url_for(site_url, path, abs_url=False):
    """Generate URL for a path"""
    if abs_url and site_url:
        return f"{site_url}/{path.lstrip('/')}"
    return f"/{path.lstrip('/')}"


def setup_template_functions(engine, site_data, config, output_dir):
    """Set up custom template functions"""

    site_url = config.get('url', '')
    if site_url:
        if not site_url.startswith(('http://', 'https://')):
            use_https = config.get('https', False)
            proto = 'https' if use_https else 'http'
            site_url = f"{proto}://{site_url}"
        site_url = site_url.rstrip('/')

    default_date_fmt = config.get('default_date_format', '%b %e, %Y')

    def url_for_func(path='', abs=False, abs_url=None):
        use_abs = abs or (abs_url == 'true') or (abs_url is True)
        if use_abs and site_url:
            return f"{site_url}/{path.lstrip('/')}"
        return f"/{path.lstrip('/')}"

    def group_func(kind='tag'):
        """Group content by kind"""
        if kind == 'tag':
            return sorted(site_data['tags'].items())
        elif kind == 'archive':
            return sorted(site_data['archives'].items(), reverse=True)
        elif kind == 'stream':
            result = []
            for s, items in site_data['streams'].items():
                result.append((s, items))
            return result
        elif kind == 'series':
            return sorted(site_data['series'].items())
        elif kind == 'author':
            return sorted(site_data['authors'].items())
        return []

    def stream_display_name_func(stream=''):
        """Get display name for a stream"""
        streams_config = config.get('streams', {})
        if stream in streams_config:
            s = streams_config[stream]
            if isinstance(s, dict):
                return s.get('display_name', stream)
        return stream

    def series_display_name_func(series=''):
        """Get display name for a series"""
        series_config = config.get('series', {})
        if series in series_config:
            s = series_config[series]
            if isinstance(s, dict):
                return s.get('display_name', series)
        return series

    def source_link_func(content=None):
        """Generate source link for content"""
        if content is None:
            return None
        source_path = content.get('source_path', '') if isinstance(content, dict) else ''
        repo = config.get('source_repository', None)
        publish_md = config.get('publish_md', False)

        if repo:
            return f"{repo}/{source_path}"
        elif publish_md:
            return source_path
        return None

    engine.add_function('url_for', url_for_func)
    engine.add_function('group', group_func)
    engine.add_function('stream_display_name', stream_display_name_func)
    engine.add_function('series_display_name', series_display_name_func)
    engine.add_function('source_link', source_link_func)

    # Add date filter
    def default_date_format_filter(value, **kwargs):
        if value is None:
            return ''
        fmt = default_date_fmt
        if isinstance(value, datetime.datetime):
            day = value.day
            result = value.strftime(fmt)
            result = result.replace('%e', str(day))
            # Handle strftime %e on platforms that don't support it
            if '%e' not in fmt:
                return result
            return result
        return str(value)

    def date_filter(value, format='%Y-%m-%d', **kwargs):
        if value is None:
            return ''
        fmt = format
        if isinstance(value, datetime.datetime):
            day = value.day
            result = value.strftime(fmt.replace('%e', str(day)))
            return result
        return str(value)

    def remove_draft_filter(value, **kwargs):
        if value is None:
            return []
        return [item for item in value if not (isinstance(item, dict) and item.get('stream') == 'draft')]

    engine.add_filter('default_date_format', default_date_format_filter)
    engine.add_filter('date', date_filter)
    engine.add_filter('remove_draft', remove_draft_filter)

    # Add 'starting_with' as a filter too (for template compatibility)
    def starting_with_filter(value, pat='', **kwargs):
        return str(value or '').startswith(str(pat))
    engine.add_filter('starting_with', starting_with_filter)


