def process_galleries(content_folder, config, skip_resize=False):
    """Process image galleries"""
    media_path = config.get('media_path', 'media')
    gallery_path = config.get('gallery_path', 'gallery')
    gallery_dir = os.path.join(content_folder, media_path, gallery_path)

    log.info(f"Processing galleries from: {gallery_dir}")

    if not os.path.exists(gallery_dir):
        log.info(f"Gallery directory does not exist: {gallery_dir}")
        return {}

    galleries = {}
    image_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.webp', '.svg'}

    for album_name in os.listdir(gallery_dir):
        album_dir = os.path.join(gallery_dir, album_name)
        if not os.path.isdir(album_dir) or album_name == 'thumbnails':
            continue

        images = []
        for fname in sorted(os.listdir(album_dir)):
            if os.path.splitext(fname)[1].lower() in image_extensions:
                images.append(fname)

        if images:
            # Create thumbnails if enabled
            if config.get('gallery_create_thumbnails', True) and not skip_resize:
                thumb_dir = os.path.join(album_dir, 'thumbnails')
                os.makedirs(thumb_dir, exist_ok=True)
                for fname in images:
                    src = os.path.join(album_dir, fname)
                    dest = os.path.join(thumb_dir, fname)
                    if not os.path.exists(dest):
                        try:
                            create_thumbnail(src, dest, config.get('gallery_thumb_size', 50))
                            log.info(f"Created thumbnail: {dest}")
                        except Exception as e:
                            log.warning(f"Could not create thumbnail for {fname}: {e}")

            galleries[album_name] = images
            log.info(f"Found gallery: {album_name} with {len(images)} files")

    log.info(f"Total galleries found: {len(galleries)}")
    return galleries


def create_thumbnail(src, dest, size=50):
    """Create a thumbnail - simplified version using PNG"""
    # Simple thumbnail creation without PIL
    # Just copy the file for now (actual resize would need PIL)
    shutil.copy2(src, dest)


# ============================================================
# SITE DATA BUILDER
# ============================================================

def build_site_data(posts, pages, config):
    """Build site data structures"""
    tags = {}  # tag -> [content_items]
    archives = {}  # year -> [content_items]
    streams = {}  # stream -> [content_items]
    series = {}  # series_name -> [content_items]
    authors = {}  # author -> [content_items]

    # All posts (including from all streams)
    all_content = posts + pages

    for item in posts:
        # Tags
        for tag in item.get('tags', []):
            if tag not in tags:
                tags[tag] = []
            tags[tag].append(item)

        # Archives (by year)
        if item.get('date'):
            year = str(item['date'].year)
            if year not in archives:
                archives[year] = []
            archives[year].append(item)

        # Streams
        stream = item.get('stream', 'index')
        if stream:
            if stream not in streams:
                streams[stream] = []
            streams[stream].append(item)

        # Series
        ser = item.get('series', None)
        if ser:
            if ser not in series:
                series[ser] = []
            series[ser].append(item)

        # Authors
        for author in item.get('authors', []):
            if author not in authors:
                authors[author] = []
            authors[author].append(item)

    # Sort all collections by date (newest first)
    for tag in tags:
        tags[tag].sort(key=lambda x: x.get('date') or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    for year in archives:
        archives[year].sort(key=lambda x: x.get('date') or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    for stream in streams:
        # Sort with pinned first
        streams[stream].sort(
            key=lambda x: (0 if x.get('pinned') else 1, 
                          -(x.get('date') or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)).timestamp())
        )

    for s in series:
        series[s].sort(key=lambda x: x.get('date') or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))

    for a in authors:
        authors[a].sort(key=lambda x: x.get('date') or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    # Build tag map for related content
    tag_map = {}
    for tag, items in tags.items():
        tag_map[slugify(tag)] = items

    # Set prev/next links for posts in streams
    # For index stream
    index_posts = [p for p in posts if p.get('stream') == 'index']
    for i, post in enumerate(index_posts):
        if i > 0:
            next_post = index_posts[i - 1]
            post['next'] = {'slug': next_post['slug'], 'title': next_post['title']}
        if i < len(index_posts) - 1:
            prev_post = index_posts[i + 1]
            post['previous'] = {'slug': prev_post['slug'], 'title': prev_post['title']}

    # Build back-links (which posts link to each post)
    if config.get('enable_related_content', True):
        slug_to_content = {p['slug']: p for p in all_content}

        for item in posts:
            # Find all internal links in content
            links = re.findall(r'href="/?([^"]+)\.html"', item.get('html', ''))
            for link_slug in links:
                if link_slug in slug_to_content:
                    target = slug_to_content[link_slug]
                    if item not in target.get('back_links', []):
                        if 'back_links' not in target:
                            target['back_links'] = []
                        target['back_links'].append({'slug': item['slug'], 'title': item['title']})

    return {
        'tags': tags,
        'archives': archives,
        'streams': streams,
        'series': series,
        'authors': authors,
        'all_posts': posts,
        'all_pages': pages,
        'pages': pages,
        'tag': {'map': tag_map},
    }


